import { QUALITY_MANAGER_INLINE_SCRIPT, QUALITY_MANAGER_INLINE_STYLES } from "./quality-manager-inline";
import { QUALITY_EMPLOYEE_INLINE_SCRIPT, QUALITY_EMPLOYEE_INLINE_STYLES } from "./quality-employee-inline";
import type { WorkbenchShellRole } from "./workbench-shell";
import { renderWorkbenchPage } from "./workbench-shell";
import { QUALITY_UNIFIED_STYLES } from "./quality-unified-styles";
import { QUALITY_TRACKING_STYLES } from "./quality-tracking-styles";
import type { QualityManagerPerspective } from
  "../quality/analysis/quality-department-directory";
import type { WorkbenchAdminPerspective } from "../security/workbench-admin-perspective";
import { HISTORICAL_FEEDBACK_TAXONOMY_V0 } from
  "../quality/ai-original-assessment/historical-feedback-taxonomy-v0";
